```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];

    long long total = 0;
    for (int i = 0; i < n; i++) {
        total += min(a[i], b[i]);
    }
    cout << total * m << endl;
    return 0;
}
