#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];

    ll total = 1LL * n * m;
    ll opens = total / 2, closes = total / 2;

    ll sum_a = 0, sum_b = 0;
    for (int i = 0; i < n; i++) {
        sum_a += a[i];
        sum_b += b[i];
    }

    ll full_cycles_a = opens / n;
    ll rem_a = opens % n;
    ll cost_a = full_cycles_a * sum_a;
    for (int i = 0; i < rem_a; i++) cost_a += a[i];

    ll full_cycles_b = closes / n;
    ll rem_b = closes % n;
    ll cost_b = full_cycles_b * sum_b;
    for (int i = 0; i < rem_b; i++) cost_b += b[i];

    cout << cost_a + cost_b << endl;
    return 0;
}
