```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    ll m;
    cin >> n >> m;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];

    ll L = (ll)n * m;
    vector<vector<ll>> dp(L + 1, vector<ll>(L / 2 + 1, LLONG_MAX));
    dp[0][0] = 0;

    for (ll i = 0; i < L; i++) {
        int ai = a[i % n];
        int bi = b[i % n];
        for (int j = 0; j <= L / 2; j++) {
            if (dp[i][j] == LLONG_MAX) continue;
            // Place '('
            if (j + 1 <= L / 2) {
                if (dp[i + 1][j + 1] > dp[i][j] + ai) {
                    dp[i + 1][j + 1] = dp[i][j] + ai;
                }
            }
            // Place ')'
            if (j > 0) {
                if (dp[i + 1][j - 1] > dp[i][j] + bi) {
                    dp[i + 1][j - 1] = dp[i][j] + bi;
                }
            }
        }
    }

    cout << dp[L][0] << endl;
    return 0;
}
