#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    long long total = 0;
    for (int i = 0; i < n * m; ++i) {
        int mod = i % n;
        total += min(a[mod], b[mod]);
    }
    cout << total << endl;
    return 0;
}
