```cpp
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int N = 22;
const ll INF = 1e18;

int n, m;
int a[N], b[N];
ll dp[N][N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    int len = n * m;
    vector<vector<ll>> dp(len + 1, vector<ll>(n + 1, INF));
    dp[0][0] = 0;
    for (int i = 0; i < len; i++) {
        for (int j = 0; j <= n; j++) {
            if (dp[i][j] == INF) continue;
            int idx = i % n;
            if (j < n) {
                dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + a[idx]);
            }
            if (j > 0) {
                dp[i + 1][j - 1] = min(dp[i + 1][j - 1], dp[i][j] + b[idx]);
            }
        }
    }
    cout << dp[len][0] << endl;
    return 0;
}
